SELECT MAX(p.stoptime - p.starttime) AS max_duration FROM prescriptions p JOIN patients pt ON p.subject_id = pt.subject_id WHERE pt.gender = 'F' AND pt.anchor_age = 43 AND EXTRACT(YEAR FROM p.starttime::DATE) BETWEEN 2015 AND 2016 AND p.drug LIKE '%ACE%inhibitor%' AND pt.anchor_year BETWEEN 2015 AND 2016 AND (pt.anchor_year_group = '38-48' OR pt.anchor_year_group = '38-48-years');